"""Embeds firmware/portal/index.html into firmware/include/portal.h as a PROGMEM raw string."""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DELIM = ')KL"'


def embed(src: Path, out: Path) -> None:
    html = Path(src).read_text(encoding="utf-8")
    if DELIM in html:
        raise ValueError("portal html contains the raw-string terminator")
    body = (
        "// GENERATED by tools/embed_portal.py from firmware/portal/index.html - do not edit.\n"
        "#pragma once\n#include <pgmspace.h>\n\n"
        'static const char PORTAL_HTML[] PROGMEM = R"KL(' + html + ')KL";\n'
    )
    Path(out).parent.mkdir(parents=True, exist_ok=True)
    Path(out).write_bytes(body.encode("utf-8"))


if __name__ == "__main__":
    embed(ROOT / "firmware" / "portal" / "index.html", ROOT / "firmware" / "include" / "portal.h")
    print("wrote firmware/include/portal.h", file=sys.stderr)
